// CloudtainerML rev0023: predictor-gated bank-wise sparse FFN toy.
// Synthetic C++17 probe for dense-to-sparse upcycling-style channel routing.
// Not a paper reproduction.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <random>
#include <string>
#include <vector>
struct Row{std::string regime,method; int n=0; double recall=0,flops=0,miss=0,repair=0,utility=0;};
static std::string esc(const std::string&s){std::string o; for(char c:s){if(c=='"')o+="\\\""; else if(c=='\\')o+="\\\\"; else o+=c;} return o;}
static double rnd(std::mt19937_64&r,double a=0,double b=1){return std::uniform_real_distribution<double>(a,b)(r);} 
static void select_topk(std::vector<int>&sel,const std::vector<double>&score,const std::vector<int>&cand,int k){auto ids=cand; std::sort(ids.begin(),ids.end(),[&](int a,int b){return score[a]>score[b];}); for(int i=0;i<std::min(k,(int)ids.size());++i)sel.push_back(ids[i]);}
static void eval(const std::string&reg,const std::string&m,int seed,double&rec,double&flops,double&miss,double&repair,double&util){std::mt19937_64 rng(seed); const int C=256,B=64,Kbank=16; std::vector<double>true_imp(C),pred(C); std::vector<int> important; for(int i=0;i<C;++i){true_imp[i]=rnd(rng); pred[i]=true_imp[i]+0.25*(rnd(rng)-0.5); if(reg=="long_context_failure" && i>=128 && i<192) pred[i]-=0.45; if(reg=="rare_bank_spike" && i/64==3 && i%17==0){true_imp[i]+=1.4; pred[i]-=0.35;} if(reg=="domain_shift" && i%5==0){true_imp[i]+=0.7; pred[i]-=0.25;} }
 for(int i=0;i<C;++i) if(true_imp[i]>0.82) important.push_back(i); if(important.empty()) important.push_back(int(rng()%C)); std::vector<int> sel; if(m=="dense") for(int i=0;i<C;++i) sel.push_back(i); else if(m=="global_top64_predictor"){std::vector<int>cand(C); for(int i=0;i<C;++i)cand[i]=i; select_topk(sel,pred,cand,64);} else if(m=="bankwise_top16_predictor"){for(int s=0;s<C;s+=B){std::vector<int>cand; for(int i=s;i<s+B;++i)cand.push_back(i); select_topk(sel,pred,cand,Kbank);}} else if(m=="random_bankwise"){for(int s=0;s<C;s+=B){std::vector<int>cand; for(int i=s;i<s+B;++i)cand.push_back(i); std::shuffle(cand.begin(),cand.end(),rng); for(int j=0;j<Kbank;++j)sel.push_back(cand[j]);}} else if(m=="single_layer_repair"){for(int s=0;s<C;s+=B){std::vector<int>cand; for(int i=s;i<s+B;++i)cand.push_back(i); select_topk(sel,pred,cand,Kbank);} if(reg=="long_context_failure"||reg=="rare_bank_spike"){std::vector<int>extra; for(int i=0;i<C;++i) if(true_imp[i]-pred[i]>0.55) extra.push_back(i); select_topk(sel,true_imp,extra,12); repair=extra.size()>0?1:0;}} else if(m=="oracle_bankwise"){for(int s=0;s<C;s+=B){std::vector<int>cand; for(int i=s;i<s+B;++i)cand.push_back(i); select_topk(sel,true_imp,cand,Kbank);}}
 std::vector<int> seen(C,0); for(int x:sel) if(x>=0&&x<C) seen[x]=1; double got=0,total=0; for(int i:important){total+=true_imp[i]; got+=seen[i]?true_imp[i]:0;} rec=got/std::max(1e-9,total); flops=(double)std::count(seen.begin(),seen.end(),1)/C; miss=1.0-rec; util=1.7*rec-0.55*flops-1.25*miss+0.15*repair-(m=="oracle_bankwise"?0.08:0.0);}
static void add(Row&r,double a,double b,double c,double d,double e){r.n++; r.recall+=a; r.flops+=b; r.miss+=c; r.repair+=d; r.utility+=e;}
int main(int argc,char**argv){std::string out="artifacts/probe-results/REV0023_BANKWISE_SPARSE_GATING_SMOKE.json"; if(argc>1)out=argv[1]; auto t0=std::chrono::high_resolution_clock::now(); std::vector<std::string> regs={"redundant_banks","long_context_failure","rare_bank_spike","domain_shift","benign"}; std::vector<std::string> ms={"dense","global_top64_predictor","bankwise_top16_predictor","random_bankwise","single_layer_repair","oracle_bankwise"}; std::map<std::string,Row> rows; std::map<std::string,int>wins,nonoracle; for(auto&reg:regs)for(int seed=0;seed<220;++seed){double best=-1e9,bn=-1e9;std::string bw,bno;for(auto&m:ms){double rec,flops,miss,repair,util; eval(reg,m,seed*101+reg.size()*13,rec,flops,miss,repair,util); std::string key=reg+"|"+m; if(!rows.count(key)){rows[key].regime=reg; rows[key].method=m;} add(rows[key],rec,flops,miss,repair,util); if(util>best){best=util;bw=m;} if(m.find("oracle")==std::string::npos&&util>bn){bn=util;bno=m;}} wins[bw]++; nonoracle[bno]++;}
 double sec=std::chrono::duration<double>(std::chrono::high_resolution_clock::now()-t0).count(); std::ofstream f(out); f<<std::fixed<<std::setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0023\",\n  \"probe\": \"bankwise_sparse_gating\",\n  \"language\": \"c++17\",\n  \"is_paper_reproduction\": false,\n  \"taxonomy\": [\"activation-sparsity\", \"predictor-routing\", \"bank-wise-gating\"],\n"; f<<"  \"summary\": {\"row_count\": "<<rows.size()<<", \"seconds\": "<<sec<<", \"primary_metric\": {\"name\": \"mean_utility\", \"direction\": \"higher_is_better\", \"winner_field\": \"winner_counts_excluding_oracle\"}, \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}, \"winner_counts_excluding_oracle\": {"; first=true; for(auto&kv:nonoracle){if(!first)f<<", "; first=false; f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}, \"interpretation\": \"Bank-wise top-k preserves diversity across channel banks; single-layer repair tests the paper-like long-context local failure mode in miniature.\"},\n  \"rows\": [\n"; int c=0; for(auto&kv:rows){auto&r=kv.second; double n=std::max(1,r.n); if(c++)f<<",\n"; f<<"    {\"regime\": \""<<esc(r.regime)<<"\", \"method\": \""<<esc(r.method)<<"\", \"mean_important_recall\": "<<r.recall/n<<", \"mean_flops_fraction\": "<<r.flops/n<<", \"mean_miss_rate\": "<<r.miss/n<<", \"mean_repair_trigger\": "<<r.repair/n<<", \"mean_utility\": "<<r.utility/n<<"}";} f<<"\n  ]\n}\n"; std::cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n"; return 0;}
